import {CASE,LOCATIONS,PEOPLE,CLUES,OBJECTS,createSession,dispatch,parseCommand,playerView,worldAt,timeLabel,distance,diagnostics,caseHealth,exportSession,importSession} from './engine.mjs';

const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const storageKey='living-mystery.bellweather.v1';
let session,saveError=false;
try{const saved=localStorage.getItem(storageKey);session=saved?importSession(saved):createSession(17);}catch{session=createSession(17);saveError=true;}
let mode='game',notebook='evidence',chat=null,chosenClue=null,inspectorTab='timeline',person='clara',personTab='profile',cursor=null,typeFilter='all',actorFilter='all',query='',includeClock=false,timer=null,healthCache=null;
const glyphs={history:'◇',arrival:'↳',command:'›',action:'◆',movement:'↗',decision:'⑂',belief:'◈',speech:'“',relationship:'↔',emotion:'≈',evidence:'+',notebook:'⌑',observation:'◉',rejected:'!',resolution:'✓',clock:'·',checkpoint:'·',memory:'⋮'};
const typeNames={history:'Case history',arrival:'Arrival',command:'Player command',action:'Action',movement:'Movement',decision:'Decision',belief:'Belief',speech:'Conversation',relationship:'Relationship',emotion:'Emotion',evidence:'Evidence',notebook:'Notebook',observation:'Observation',rejected:'Rejected action',resolution:'Resolution',clock:'Clock',checkpoint:'Checkpoint',memory:'Memory'};
function avatar(id,size=''){const p=PEOPLE[id];return `<span class="avatar ${size}" style="--person:${p.color}">${p.initials}</span>`;}
function actorName(id){return PEOPLE[id]?.name??(id==='player'?'You':id==='world'?'World':'Simulation');}
function placeName(id){return LOCATIONS[id]?.name??(id==='transit'?'In transit':id==='drawer'?'Vestry · deed drawer':id==='silas'?'Carried by Silas':id??'—');}
function eventById(id){return session.events.find(e=>e.id===id);}
function selectedIndex(){return cursor===null?session.events.length-1:Math.min(cursor,session.events.length-1);}
function selectedWorld(){return cursor===null?session.world:worldAt(session,selectedIndex());}
function selectEvent(index){cursor=Number(index);if(cursor<0||cursor>=session.events.length)cursor=null;stopReplay();render();}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4200);}
function persist(){try{localStorage.setItem(storageKey,exportSession(session));saveError=false;}catch{saveError=true;toast('This browser could not save the investigation. Use Export to keep a copy.');}}
function act(action){stopReplay();cursor=null;try{dispatch(session,action);healthCache=null;persist();render();const j=$('#journal');if(j)j.scrollTop=j.scrollHeight;}catch(error){toast(`The action could not be completed: ${error.message}`);}}
function getHealth(){if(!healthCache||healthCache.eventCount!==session.events.length)healthCache=diagnostics(session);return healthCache;}
function paragraphs(text){return String(text).split('\n\n').map(p=>`<p>${esc(p).replaceAll('\n','<br>')}</p>`).join('');}

function header(){return `<header class="topbar">
  <button class="brand" data-do="mode" data-value="game" aria-label="Return to the investigation"><span class="brand-mark">L<span>M</span></span><span><strong>Living Mystery</strong><small>BELLWEATHER · CASE 01</small></span></button>
  <nav class="mode-switch" aria-label="Application mode"><button class="${mode==='game'?'active':''}" data-do="mode" data-value="game" aria-pressed="${mode==='game'}">Investigation</button><button class="${mode==='inspector'?'active':''}" data-do="mode" data-value="inspector" aria-pressed="${mode==='inspector'}">Inspector <span class="small-symbol">⌘</span></button></nav>
  <div class="top-tools"><div class="world-time"><strong>${timeLabel(session.world.minute)}</strong><span>${CASE.date}</span></div><button class="icon-button" data-do="menu" aria-label="Save, import, restart, and help">•••</button></div>
</header>`;}

function game(){const v=playerView(session);if(chat&&!v.people.some(p=>p.id===chat))chat=null;return `<div class="game-shell">
  <aside class="village-panel panel" aria-label="Village navigation"><div class="panel-heading"><span class="eyebrow">BELLWEATHER</span><span class="meta">6 places</span></div><h2 class="section-heading">The village</h2><nav class="places">${Object.entries(LOCATIONS).map(([id,p])=>`<button data-do="move" data-id="${id}" class="place ${v.location===id?'current':''}" ${v.status==='solved'?'disabled':''} aria-current="${v.location===id?'location':'false'}"><span class="place-num">${p.glyph}</span><span><strong>${p.name}</strong><small>${v.location===id?'You are here':`${distance(v.location,id)} min walk`}</small></span>${v.location===id?'<span class="here-mark" aria-hidden="true"></span>':''}</button>`).join('')}</nav>
  <div class="side-rule"></div><div class="panel-heading"><span class="eyebrow">WITHIN EARSHOT</span><span class="meta">${v.people.length} here</span></div><div class="people-here">${v.people.map(p=>`<button class="person-row ${chat===p.id?'selected':''}" data-do="chat" data-id="${p.id}">${avatar(p.id)}<span><strong>${p.name}</strong><small>${p.role}</small></span><span class="chevron">›</span></button>`).join('')||'<p class="muted quiet">No one else is here.</p>'}</div>
  <div class="village-footer"><button class="subtle-button" data-do="wait">◷ &nbsp; Wait 10 minutes</button><p class="meta">Time passes when you act.<br>Read and think at your own pace.</p></div></aside>
  <main class="story-panel panel"><div class="scene-heading"><div class="eyebrow gold">THE LAST BELL <span class="divider">/</span> ${v.status==='solved'?'CASE CLOSED':'AN INVESTIGATION'}</div><h1>${v.status==='solved'?'A case made.':v.scene.name}</h1><p class="scene-atmosphere">${v.status==='solved'?'The village will remember how you found the truth.':v.scene.atmosphere}</p></div>
  <div class="journal" id="journal" role="log" aria-label="Your investigation history" aria-live="polite">${v.transcript.map((e,i)=>`<article class="journal-entry ${e.kind==='speech'?'spoken':''} ${e.kind==='evidence'?'clue-found':''} ${e.kind==='resolution'?'resolution':''}"><div class="journal-meta"><span>${timeLabel(e.minute)}</span><span>${e.kind==='speech'?esc(actorName(e.actor)):e.kind==='evidence'?'NOTEBOOK ENTRY':e.kind==='rejected'?'INVESTIGATION':i===0?'YOUR ARRIVAL':e.kind==='resolution'?'CASE CLOSED':'OBSERVATION'}</span></div><div class="journal-prose">${paragraphs(e.text)}</div></article>`).join('')}</div>
  <section class="action-area" aria-label="Available actions">${v.status==='solved'?`<div class="solved-actions"><span class="gold">✓ &nbsp; Your evidence supported the accusation.</span><button class="primary" data-do="mode" data-value="inspector">Explore the full history</button></div>`:chat?conversation(v):`<div class="panel-heading"><span class="eyebrow">YOUR SURROUNDINGS</span><span class="meta">Inspection takes 3 min</span></div><div class="object-actions">${v.scene.objects.map(id=>`<button class="object-button" data-do="inspect" data-id="${id}"><span>${OBJECTS[id].label}</span><small>${OBJECTS[id].description}</small></button>`).join('')||`<button class="object-button prominent" data-do="move" data-id="manor"><span>Begin at Vale Manor <b>↗</b></span><small>Examine the study and its records</small></button><button class="object-button" data-do="chat" data-id="bell"><span>Speak with Constable Bell</span><small>Ask about the investigation</small></button>`}</div>`}</section>
  <form class="command-line" id="command-form"><span aria-hidden="true">›</span><label for="command" class="sr-only">Type a supported game command</label><input id="command" name="command" autocomplete="off" placeholder="Try ‘go manor’ or ‘ask Clara about alibi’" ${v.status==='solved'?'disabled':''}><button type="submit" aria-label="Run command">↵</button></form></main>
  <aside class="notebook-panel panel" aria-label="Your notebook"><div class="panel-heading"><span class="eyebrow">YOUR CASE FILE</span><span class="meta">${v.evidence.length} entries</span></div><h2 class="section-heading">The notebook</h2><div class="small-tabs" role="tablist" aria-label="Notebook views">${[['evidence','Evidence'],['people','People'],['notes','Hypotheses']].map(([id,label])=>`<button role="tab" aria-selected="${notebook===id}" class="${notebook===id?'active':''}" data-do="notebook" data-id="${id}">${label}</button>`).join('')}</div><div class="notebook-content">${notebookContent(v)}</div><div class="notebook-footer"><span class="meta">${v.pins.length} pinned for your case</span><button class="primary full" data-do="accusation">${v.status==='solved'?'Review your accusation':'Make an accusation'} <span>↗</span></button><span class="save-note">${saveError?'Not saved · export a copy':'Saved on this device'}</span></div></aside>
</div>`;}

function conversation(v){const p=PEOPLE[chat];if(!v.evidence.some(e=>e.clue===chosenClue))chosenClue=v.evidence[0]?.clue??null;return `<div class="conversation-head">${avatar(chat)}<span><strong>${p.name}</strong><small>${p.role}</small></span><button class="icon-button close-small" data-do="close-chat" aria-label="Close conversation">×</button></div><div class="dialogue-options"><button class="text-action" data-do="ask" data-person="${chat}" data-topic="${chat==='bell'?'case':'alibi'}">${chat==='bell'?'Ask what makes a convincing case':'Ask about last night'} <span>3 min</span></button><button class="text-action" data-do="ask" data-person="${chat}" data-topic="accounts">${chat==='bell'?'Ask for a lead':chat==='ada'?'Ask what she actually saw':'Ask about the accounts'} <span>3 min</span></button></div>${v.evidence.length?`<div class="present-controls"><label for="present-clue">Show evidence</label><select id="present-clue">${v.evidence.map(e=>`<option value="${e.clue}" ${e.clue===chosenClue?'selected':''}>${e.title}</option>`).join('')}</select>${chat==='clara'&&['letter','record'].includes(chosenClue)?`<div class="two-actions"><button class="soft-button" data-do="present" data-person="clara" data-tone="private">Offer discretion</button><button class="soft-button danger-soft" data-do="present" data-person="clara" data-tone="press">Threaten exposure</button></div>`:`<button class="soft-button" data-do="present" data-person="${chat}" data-tone="private">Present & discuss</button>`}</div>`:'<p class="meta">Discover evidence to present it in conversation.</p>'}`;}

function notebookContent(v){
  if(notebook==='evidence')return v.evidence.length?v.evidence.slice().reverse().map(e=>`<article class="evidence-card ${v.pins.includes(e.clue)?'pinned':''}"><button class="evidence-open" data-do="clue" data-id="${e.clue}"><span class="eyebrow kind-label">${e.kind}</span><strong>${e.title}</strong><small>${esc(e.source)}</small></button><button class="pin-button ${v.pins.includes(e.clue)?'on':''}" data-do="pin" data-id="${e.clue}" aria-label="${v.pins.includes(e.clue)?'Unpin':'Pin'} ${e.title}" aria-pressed="${v.pins.includes(e.clue)}">${v.pins.includes(e.clue)?'◆':'◇'}</button></article>`).join(''):`<div class="empty-notebook"><span class="empty-symbol">⌑</span><h3>A fresh page.</h3><p>What you discover and what people tell you will appear here.</p><p class="meta">Begin with the study at Vale Manor.</p></div>`;
  if(notebook==='people')return Object.entries(PEOPLE).map(([id,p])=>{const seen=v.lastSeen[id];return `<div class="notebook-person">${avatar(id)}<div><strong>${p.name}</strong><span>${p.role}</span><p>${p.public}</p><small>${v.people.some(x=>x.id===id)?'Here with you':seen?`Last seen: ${placeName(seen.location)} · ${timeLabel(seen.minute)}${seen.departed?' (departed)':''}`:'Not yet encountered'}</small></div></div>`;}).join('');
  return `<p class="muted">Keep your own theories. A hypothesis stays separate from a discovered fact.</p><form id="note-form"><label class="sr-only" for="note">Your hypothesis</label><textarea id="note" name="note" rows="4" maxlength="1000" placeholder="What do you think happened?"></textarea><button class="soft-button full" type="submit">Add hypothesis</button></form><div class="notes-list">${v.notes.slice().reverse().map(n=>`<article><span class="meta">${timeLabel(n.minute)}</span><p>${esc(n.text)}</p></article>`).join('')}</div>`;
}

function inspector(){const w=selectedWorld(),health=getHealth();return `<main class="inspector-shell">
  <div class="inspector-heading"><div><div class="eyebrow teal">SIMULATION INSPECTOR</div><h1>Behind the story</h1><p>Follow what happened, who knew, and why they acted.</p></div><div class="inspector-summary"><div><strong>${session.events.length}</strong><span>recorded events</span></div><div><strong>${Object.values(w.npcs).reduce((n,a)=>n+a.beliefs.length,0)}</strong><span>traced beliefs</span></div><button class="health-pill ${health.ok?'good':'bad'}" data-do="inspector-tab" data-id="checks">${health.ok?'✓ Replay verified':'! Check failed'}</button></div></div>
  <div class="inspector-nav"><nav class="wide-tabs" aria-label="Inspector views">${[['timeline','Event history'],['world','World & case'],['checks','Integrity checks']].map(([id,label])=>`<button class="${inspectorTab===id?'active':''}" data-do="inspector-tab" data-id="${id}">${label}</button>`).join('')}</nav><span class="spoiler-label">Hidden case facts visible</span><button class="subtle-button export-trace" data-do="export">Export full trace ↗</button></div>
  <div class="inspector-workspace ${inspectorTab!=='timeline'?'alternate-view':''}">${inspectorTab==='timeline'?`<aside class="event-list-panel"><div class="event-filters"><label class="sr-only" for="history-search">Search event history</label><input id="history-search" placeholder="Search the history…" value="${esc(query)}"><div class="filter-row"><label class="sr-only" for="actor-filter">Filter by person</label><select id="actor-filter"><option value="all">Everyone</option><option value="player" ${actorFilter==='player'?'selected':''}>You</option>${Object.entries(PEOPLE).map(([id,p])=>`<option value="${id}" ${actorFilter===id?'selected':''}>${p.name}</option>`).join('')}</select><label class="sr-only" for="type-filter">Filter by event type</label><select id="type-filter"><option value="all">All activity</option>${Object.entries(typeNames).filter(([id])=>!['clock','checkpoint','memory'].includes(id)).map(([id,n])=>`<option value="${id}" ${typeFilter===id?'selected':''}>${n}</option>`).join('')}</select></div><label class="clock-filter"><input type="checkbox" id="clock-filter" ${includeClock?'checked':''}> Include clock, memory & checkpoints</label></div><div id="event-list" class="event-list">${eventList()}</div></aside><section class="event-detail" id="event-detail">${eventDetail()}</section>`:inspectorTab==='world'?worldPanel(w):checksPanel(health)}<aside class="character-panel" id="character-panel">${characterPanel(w)}</aside></div>
  ${replayBar()}
</main>`;}

function filteredEvents(){return session.events.filter(e=>(includeClock||!['clock','memory','checkpoint'].includes(e.kind))&&(typeFilter==='all'||e.kind===typeFilter)&&(actorFilter==='all'||e.actor===actorFilter||e.data.listener===actorFilter)&&(query===''||`${e.title} ${actorName(e.actor)} ${e.data.reason??''} ${e.id}`.toLowerCase().includes(query.toLowerCase())));}
function eventList(){const events=filteredEvents();return `<div class="event-list-label"><span>${events.length} events</span><span>Newest first</span></div>${events.slice().reverse().map(e=>`<button class="event-row ${selectedIndex()===e.index?'selected':''} ${e.index>selectedIndex()?'future':''}" data-do="event" data-index="${e.index}"><span class="event-dot kind-${e.kind}">${glyphs[e.kind]??'·'}</span><span class="event-row-copy"><span class="event-row-meta"><time>${timeLabel(e.minute)}</time><span>${e.id}</span></span><strong>${esc(e.title)}</strong><small>${typeNames[e.kind]}${e.playerText?' · observed':''}</small></span></button>`).join('')||'<p class="empty-state">No events match these filters.</p>'}`;}
function compact(value){if(value===null||value===undefined)return '—';if(typeof value==='boolean')return value?'Yes':'No';if(typeof value==='number')return Number.isInteger(value)?String(value):value.toFixed(2);if(typeof value==='string')return value;if(Array.isArray(value)){if(value.length===0)return 'Empty';if(value[0]?.key)return value.map(x=>x.text).join(' • ');if(value[0]?.clue)return value.map(x=>CLUES[x.clue]?.title??x.clue).join(', ');return value.map(x=>typeof x==='object'?JSON.stringify(x):x).join(', ');}return JSON.stringify(value);}
function pathLabel(path){const parts=path.split('.');if(parts[0]==='npcs')return `${PEOPLE[parts[1]]?.name??parts[1]} / ${parts.slice(2).join(' / ')}`;return path.replaceAll('.',' / ');}
function eventLink(e,label){return e?`<button class="event-link" data-do="event" data-index="${e.index}"><span>${e.id}</span>${esc(label??e.title)} <b>↗</b></button>`:'';}

function eventDetail(){const e=session.events[selectedIndex()];if(!e)return '<p>Select an event.</p>';const children=session.events.filter(x=>x.parents.includes(e.id)&&!['clock','checkpoint','memory'].includes(x.kind));const candidates=e.data.candidates;
  return `<div class="detail-kicker"><span class="type-badge kind-${e.kind}">${glyphs[e.kind]??'·'} &nbsp; ${typeNames[e.kind]??e.kind}</span><span class="meta">${e.id} · ${timeLabel(e.minute)}</span></div><h2>${esc(e.title)}</h2><div class="event-context"><button class="actor-chip" data-do="person" data-id="${PEOPLE[e.actor]?e.actor:person}">${PEOPLE[e.actor]?avatar(e.actor,'tiny'):''}${esc(actorName(e.actor))}</button><span>${esc(placeName(e.location))}</span><span class="visibility-badge">${e.playerText?'Player observed':'Internal / offstage'}</span></div>
  ${e.playerText?`<blockquote class="event-quote">${paragraphs(e.playerText)}</blockquote>`:''}
  ${e.data.reason||e.data.intent?`<section class="detail-section"><h3>${e.data.intent?'Communicative intent':'Recorded reason'}</h3><p>${esc(e.data.intent??e.data.reason)}</p>${e.data.basis?`<p class="meta">Belief used: ${esc(e.data.basis)}</p>`:''}${e.data.deception?`<span class="warning-label">${esc(e.data.deception)}</span>`:''}</section>`:''}
  ${e.data.assertion?`<section class="detail-section"><h3>Assertion</h3><p>${esc(e.data.assertion)}</p><span class="meta">Addressed to ${esc(actorName(e.data.listener))}. An assertion is not automatically a fact.</span></section>`:''}
  ${e.data.belief?`<section class="detail-section"><h3>Belief acquired</h3>${beliefCard(e.data.belief)}</section>`:''}
  ${candidates?`<section class="detail-section"><h3>Alternatives considered</h3><p class="meta">Scores are recorded policy values, not reconstructed explanations.</p><div class="candidate-list">${candidates.map(c=>`<article class="candidate ${c.id===e.data.selected?'chosen':''}"><div><strong>${esc(c.label)}</strong><span>${c.score}</span></div><div class="score-track"><span style="width:${c.score}%"></span></div><p>${c.reasons.map(esc).join(' ')}</p>${c.id===e.data.selected?'<span class="chosen-label">✓ Chosen</span>':''}</article>`).join('')}</div></section>`:''}
  ${e.changes.length?`<section class="detail-section"><div class="panel-heading"><h3>What changed</h3><span class="meta">${e.changes.length} ${e.changes.length===1?'field':'fields'}</span></div><div class="changes">${e.changes.map(p=>`<div class="change"><strong>${esc(pathLabel(p.path))}</strong><div class="before-after"><span class="before"><small>BEFORE</small>${esc(compact(p.before))}</span><span class="after"><small>AFTER</small>${esc(compact(p.after))}</span></div></div>`).join('')}</div></section>`:`<p class="no-mutation">This event records context or intent without changing a world field.</p>`}
  <section class="detail-section causal-section"><h3>Follow the causes</h3>${e.parents.length?e.parents.map(id=>eventLink(eventById(id))).join(''):'<p class="meta">This is an initial case event.</p>'}</section>
  ${children.length?`<section class="detail-section causal-section"><h3>What followed from this</h3>${children.slice(0,12).map(child=>eventLink(child)).join('')}${children.length>12?`<p class="meta">${children.length-12} additional events in the full trace.</p>`:''}</section>`:''}
  <details class="raw-event"><summary>Inspect structured event</summary><pre>${esc(JSON.stringify(e,null,2))}</pre></details>`;
}

function beliefCard(b){return `<article class="belief-card"><div><span class="truth-badge ${b.truth===true?'true':b.truth===false?'false':'unknown'}">${b.truth===true?'Matches case truth':b.truth===false?'Mistaken belief':'Not established'}</span><span class="meta">${Math.round(b.confidence*100)}% confidence</span></div><p>${esc(b.text)}</p><small>${esc(b.sourceType)} · acquired ${timeLabel(b.acquired)}</small>${eventLink(eventById(b.sourceId),'View the source event')}</article>`;}
function characterPanel(w){const p=PEOPLE[person],a=w.npcs[person],idx=selectedIndex();return `<div class="character-top"><span class="eyebrow">CHARACTER INSPECTOR</span><label class="sr-only" for="character-select">Choose a character</label><select id="character-select">${Object.entries(PEOPLE).map(([id,p])=>`<option value="${id}" ${person===id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="profile-heading">${avatar(person,'large')}<h2>${p.name}</h2><p>${p.role}</p><span class="meta">${esc(a.travel?`${placeName(a.travel.from)} → ${placeName(a.travel.to)}`:placeName(a.location))}</span><span class="at-time">${cursor===null?'PRESENT':`AT EVENT ${session.events[idx].id}`} · ${timeLabel(w.minute)}</span></div>
  <div class="small-tabs profile-tabs" role="tablist" aria-label="Character views">${[['profile','Profile'],['beliefs',`Beliefs (${a.beliefs.length})`],['history','History']].map(([id,n])=>`<button class="${personTab===id?'active':''}" role="tab" aria-selected="${personTab===id}" data-do="person-tab" data-id="${id}">${n}</button>`).join('')}</div><div class="profile-content">${personTab==='beliefs'?a.beliefs.map(beliefCard).join(''):personTab==='history'?`<p class="meta">Actions, perceptions, and updates involving ${p.name.split(' ')[0]}, through the selected moment.</p><button class="soft-button full" data-do="filter-person" data-id="${person}">Filter the full timeline</button>${session.events.filter(e=>e.index<=idx&&(e.actor===person||e.data.listener===person)&&!['memory','clock'].includes(e.kind)).slice(-25).reverse().map(e=>`<div class="personal-event"><span class="meta">${timeLabel(e.minute)} · ${typeNames[e.kind]}</span>${eventLink(e)}</div>`).join('')}`:`<p class="profile-bio">${p.public}</p><details class="private-background" open><summary>Private background</summary><p>${p.secret}</p></details><div class="profile-section"><h3>Current intention</h3><p class="intention">${esc(a.intention)}</p>${eventLink(eventById(a.lastDecision),'See the decision')}</div><div class="profile-section"><h3>Current state</h3>${meter('Trust in you',a.trust,'teal')}${meter('Stress',a.stress,'amber')}</div><div class="profile-section"><h3>Competing goals</h3><ol class="goal-list">${p.goals.map(g=>`<li>${g}</li>`).join('')}</ol></div><div class="profile-section"><h3>Disposition</h3>${Object.entries(p.traits).map(([k,v])=>meter(k==='riskAversion'?'Risk aversion':k[0].toUpperCase()+k.slice(1),v,'muted-meter')).join('')}</div><div class="profile-section"><h3>Values</h3><div class="value-tags">${p.values.map(v=>`<span>${v}</span>`).join('')}</div></div><div class="profile-section"><h3>Relationships</h3>${Object.entries(p.relationships).filter(([id])=>id!=='player').map(([id,r])=>`<button class="relationship-row" data-do="person" data-id="${id}">${avatar(id,'tiny')}<span>${PEOPLE[id].name}</span><small>${Math.round(r.trust*100)}% trust</small></button>`).join('')}<p class="meta">These are initial ties. Trust in you changes through play.</p></div>`}</div>`;}
function meter(label,value,kind){return `<div class="meter ${kind}"><div><span>${label}</span><strong>${Math.round(value*100)}<small>/100</small></strong></div><div class="meter-track"><span style="width:${Math.max(0,Math.min(100,value*100))}%"></span></div></div>`;}

function worldPanel(w){return `<section class="world-panel"><div class="world-panel-heading"><span class="eyebrow teal">WORLD AT ${timeLabel(w.minute)}</span><h2>A single world. Different accounts.</h2><p class="muted">The locations below show actual positions at the selected event.</p></div><div class="location-grid">${Object.entries(LOCATIONS).map(([id,p])=>`<article class="location-card"><div><span class="place-num">${p.glyph}</span><h3>${p.name}</h3></div><div class="occupants">${Object.entries(w.npcs).filter(([,a])=>a.location===id).map(([id])=>`<button data-do="person" data-id="${id}">${avatar(id,'tiny')}${PEOPLE[id].name}</button>`).join('')}${w.player.location===id?'<span class="player-occupant">You are here</span>':''}${!Object.values(w.npcs).some(a=>a.location===id)&&w.player.location!==id?'<span class="meta">Unoccupied</span>':''}</div></article>`).join('')}</div>${Object.entries(w.npcs).some(([,a])=>a.travel)?`<div class="transit-list"><h3>In transit</h3>${Object.entries(w.npcs).filter(([,a])=>a.travel).map(([id,a])=>`<p>${PEOPLE[id].name}: ${placeName(a.travel.from)} → ${placeName(a.travel.to)} <span class="meta">arrives ${timeLabel(a.travel.arrival)}</span></p>`).join('')}</div>`:''}<section class="detail-section"><h3>Evidence that can move</h3><div class="object-state"><span class="folio-mark">F</span><div><strong>The red transfer folio</strong><p>${placeName(w.objects.folio)}</p></div><span class="meta">${w.player.evidence.some(e=>e.clue==='folio')?'Contents recorded in your notebook':'Contents not yet recorded'}</span></div></section><section class="detail-section"><h3>Authored evidence routes</h3><p class="meta">These are explicit requirements for this case. They do not constitute a general solvability proof.</p><div class="proof-routes">${caseHealth(session,w).map(r=>`<article><div class="panel-heading"><strong>${r.title}</strong><span class="teal">${r.found.length}/${r.all.length}</span></div><div class="route-track"><span style="width:${100*r.found.length/r.all.length}%"></span></div><ul>${r.all.map(c=>`<li class="${r.found.includes(c)?'found':''}"><span>${r.found.includes(c)?'✓':'○'}</span>${CLUES[c].title}</li>`).join('')}</ul></article>`).join('')}</div></section><details class="truth-panel"><summary>The canonical crime history <span>Reveals the complete solution</span></summary><p>${CASE.truth}</p><div class="crime-timeline">${CASE.history.map(([t,txt])=>`<div><time>${t}</time><p>${txt}</p></div>`).join('')}</div></details><p class="meta">Schedule seed ${session.seed} · This first case is authored; changing the seed varies routines, not the culprit.</p></section>`;}

function checksPanel(h){return `<section class="checks-panel"><span class="eyebrow teal">INTEGRITY & REPLAY</span><h2>${h.ok?'The recorded world is consistent.':'There is something to inspect.'}</h2><p class="muted">These checks run against the full current history, even when you are inspecting the past.</p><div class="check-summary"><strong>${h.eventCount}</strong><span>events</span><strong>${h.patchCount}</strong><span>state changes</span></div><div class="check-list">${h.checks.map(c=>`<article><span class="check-icon ${c.ok?'good':'bad'}">${c.ok?'✓':'!'}</span><div><strong>${c.name}</strong><p>${c.ok?'Pass':'Needs attention'}</p></div></article>`).join('')}</div>${h.errors.length?`<pre class="error-list">${esc(h.errors.join('\n'))}</pre>`:''}<div class="check-explanation"><h3>What replay verification means</h3><p>Starting with the initial world, the inspector applies every recorded state change in order. The result must exactly match the current world. Every “before” value must also match the reconstructed state.</p><h3>What it does not establish</h3><p>Replay consistency alone does not establish that the mystery is fair or that the rules mean what the author intended. This prototype uses a small authored case, deterministic decisions, and scripted conversations.</p><h3>Follow a useful example</h3><p>Show the estate accounts to Silas, then let time pass. In the history, follow the conversation to his new belief, his concealment decision, and the red folio’s movement. Or threaten Clara and follow the warning to Rowan.</p><button class="soft-button" data-do="export">Export events and current state</button></div></section>`;}

function replayBar(){const idx=selectedIndex(),e=session.events[idx];return `<div class="replay-bar"><div class="replay-state"><span class="${cursor===null?'live-dot':'past-dot'}"></span><strong>${cursor===null?'Present':'Inspecting the past'}</strong><span>${timeLabel(e.minute)}</span></div><div class="replay-controls"><button class="icon-button" data-do="first" aria-label="Go to the first event">|‹</button><button class="icon-button" data-do="previous" aria-label="Previous event">‹</button><button class="play-replay" data-do="play-replay" aria-label="${timer?'Pause':'Play'} recorded history">${timer?'Ⅱ':'▶'}</button><button class="icon-button" data-do="next" aria-label="Next event">›</button></div><div class="replay-slider"><label for="history-cursor" class="sr-only">Inspect event in history</label><input id="history-cursor" type="range" min="0" max="${session.events.length-1}" value="${idx}"><span>${idx+1} / ${session.events.length} events</span></div><button class="soft-button" data-do="live" ${cursor===null?'disabled':''}>Return to present</button></div>`;}

function render(){const scrolls={};for(const selector of ['#journal','#event-list','#event-detail','#character-panel','.notebook-content']){const el=$(selector);if(el)scrolls[selector]=el.scrollTop;}$('#app').innerHTML=header()+(mode==='game'?game():inspector());document.body.dataset.mode=mode;for(const [selector,value]of Object.entries(scrolls)){const el=$(selector);if(el)el.scrollTop=value;}}
function openModal(content,label){stopReplay();const m=$('#modal');m.innerHTML=`<button class="dialog-close icon-button" data-do="close-modal" aria-label="Close dialog">×</button>${content}`;m.setAttribute('aria-label',label);if(!m.open)m.showModal();}
function clueModal(id){const c=CLUES[id],entry=session.world.player.evidence.find(e=>e.clue===id);if(!entry)return;openModal(`<div class="eyebrow gold">${c.kind}</div><h2>${c.title}</h2><p class="clue-source">${esc(entry.source)} · ${timeLabel(entry.minute)}</p><div class="dialog-prose"><p>${c.text}</p></div><div class="value-tags">${c.tags.map(t=>`<span>${t}</span>`).join('')}</div><button class="primary full" data-do="pin-close" data-id="${id}">${session.world.player.pins.includes(id)?'Unpin from your case':'Pin for your accusation'}</button>`,'Evidence detail');}
function accusationModal(){const w=session.world;if(w.status==='solved'){openModal(`<div class="eyebrow gold">CASE CLOSED</div><h2>Your accusation</h2><p>You identified Silas Voss, the brass seal, and the diverted payments.</p><div class="dialog-prose"><p>${CASE.truth}</p></div><h3>Your supporting evidence</h3><ul>${w.ending.evidence.map(c=>`<li>${CLUES[c].title}</li>`).join('')}</ul>`,'Your completed accusation');return;}
  if(w.player.location!=='square'){openModal(`<div class="eyebrow gold">PRESENT YOUR CASE</div><h2>Speak to Constable Bell.</h2><p>Bell is at the village square. Bring your notebook and explain the connection between the suspect, the act, and the motive.</p><button class="primary full" data-do="visit-bell">Go to the square · ${distance(w.player.location,'square')} min</button>`,'Visit the constable');return;}
  if(!w.player.evidence.length){openModal('<h2>A case needs evidence.</h2><p>Begin in the study at Vale Manor. Record what you find before making an accusation.</p>','Evidence needed');return;}
  const selected=w.player.pins.length?w.player.pins:w.player.evidence.map(e=>e.clue);openModal(`<div class="eyebrow gold">CONSTABLE BELL’S CASE FILE</div><h2>Make the connections.</h2><p>Select the evidence supporting your account. An unsupported accusation will not end the investigation.</p><form id="accusation-form"><div class="accusation-fields"><label>Who killed Edmund?<select name="suspect" required><option value="">Choose a suspect</option>${['clara','rowan','silas'].map(id=>`<option value="${id}">${PEOPLE[id].name}</option>`).join('')}</select></label><label>How?<select name="method" required><option value="">Choose a method</option><option value="poison">Poison in his drink</option><option value="seal">A blow from the brass seal</option><option value="knife">A concealed knife</option></select></label><label>Why?<select name="motive" required><option value="">Choose a motive</option><option value="jealousy">Jealousy over a relationship</option><option value="inheritance">An inheritance dispute</option><option value="fraud">Conceal the diverted estate payments</option></select></label></div><fieldset class="evidence-selection"><legend>Supporting evidence</legend>${w.player.evidence.map(e=>`<label><input type="checkbox" name="evidence" value="${e.clue}" ${selected.includes(e.clue)?'checked':''}><span>${CLUES[e.clue].title}<small>${CLUES[e.clue].kind}</small></span></label>`).join('')}</fieldset><button class="primary full" type="submit">Present the accusation</button></form>`,'Present an accusation');}
function menuModal(){openModal(`<div class="eyebrow gold">THE BELLWEATHER CASE</div><h2>Your investigation</h2><p>Progress is saved on this device. Export keeps a portable copy, including the full inspector history.</p><div class="menu-actions"><button class="soft-button" data-do="export">Export investigation & trace</button><button class="soft-button" data-do="import">Import saved investigation</button><button class="soft-button" data-do="help">How to investigate</button><button class="soft-button" data-do="restart-confirm">Restart this case</button></div>`,'Investigation options');}
function helpModal(){openModal(`<div class="eyebrow gold">FIELD NOTES</div><h2>Follow the evidence.</h2><p>Choose a place, inspect its objects, and speak to the people you encounter. Their whereabouts can change while you act. Time stands still while you read.</p><p>Click a notebook entry to read it, or pin it for your accusation. Present evidence in conversations to challenge a story or build trust. You can recover from a poor approach.</p><h3>Supported text commands</h3><div class="command-examples"><code>go manor</code><code>inspect desk</code><code>ask Clara about alibi</code><code>wait 10</code><code>look</code></div><p>Use the on-screen controls to present evidence and make an accusation. This first version uses authored conversations and a command parser.</p><h3>The inspector</h3><p>Inspector reveals the complete case. Select any event to see its causes and changes, move the history slider to inspect past state, and open a character’s beliefs to trace their sources.</p>`,'How to investigate');}
function exportFile(){const blob=new Blob([exportSession(session)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`bellweather-investigation-${session.events.length}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Investigation and full history exported.');}
function stopReplay(){if(timer){clearInterval(timer);timer=null;}}
function step(direction){stopReplay();cursor=Math.max(0,Math.min(session.events.length-1,selectedIndex()+direction));render();}

document.addEventListener('click',event=>{const b=event.target.closest('[data-do]');if(!b||b.disabled)return;const id=b.dataset.id,action=b.dataset.do;
  if(action==='mode'){
    if(b.dataset.value==='inspector'&&mode!=='inspector'){openModal(`<div class="eyebrow teal">SIMULATION INSPECTOR</div><h2>See behind the story.</h2><p>The inspector exposes the culprit, private beliefs, and offstage events. You can return to the investigation at any time.</p><button class="primary full" data-do="enter-inspector">Open inspector</button>`,'Open inspector with hidden case information');}
    else{mode=b.dataset.value;stopReplay();render();}return;
  }
  switch(action){
    case 'enter-inspector':$('#modal').close();mode='inspector';render();break;
    case 'move':chat=null;act({type:'move',to:id});break;
    case 'inspect':act({type:'inspect',object:id});break;
    case 'wait':act({type:'wait',minutes:10});break;
    case 'chat':chat=id;chosenClue=null;render();break;
    case 'close-chat':chat=null;render();break;
    case 'ask':act({type:'ask',person:b.dataset.person,topic:b.dataset.topic});break;
    case 'present':if(chosenClue)act({type:'present',person:b.dataset.person,clue:chosenClue,tone:b.dataset.tone});break;
    case 'notebook':notebook=id;render();break;
    case 'pin':act({type:'pin',clue:id});break;
    case 'pin-close':$('#modal').close();act({type:'pin',clue:id});break;
    case 'clue':clueModal(id);break;
    case 'accusation':accusationModal();break;
    case 'visit-bell':$('#modal').close();chat=null;act({type:'move',to:'square'});accusationModal();break;
    case 'menu':menuModal();break;
    case 'close-modal':$('#modal').close();break;
    case 'help':helpModal();break;
    case 'export':exportFile();break;
    case 'import':$('#import-file').click();break;
    case 'restart-confirm':openModal(`<div class="eyebrow gold">RESTART THE LAST BELL</div><h2>Return to the beginning?</h2><p>Your current investigation will be replaced on this device. Export it first if you want to keep its history. This remains the same authored case.</p><div class="menu-actions"><button class="soft-button" data-do="export">Export current investigation</button><button class="primary" data-do="restart">Restart from 08:00</button></div>`,'Restart this investigation');break;
    case 'restart':session=createSession(session.seed);healthCache=null;cursor=null;chat=null;stopReplay();persist();$('#modal').close();render();toast('A new morning in Bellweather.');break;
    case 'event':selectEvent(b.dataset.index);break;
    case 'person':if(PEOPLE[id]){person=id;personTab='profile';render();}break;
    case 'person-tab':personTab=id;render();break;
    case 'filter-person':actorFilter=id;typeFilter='all';query='';inspectorTab='timeline';render();break;
    case 'inspector-tab':inspectorTab=id;render();break;
    case 'first':selectEvent(0);break;
    case 'previous':step(-1);break;
    case 'next':step(1);break;
    case 'live':stopReplay();cursor=null;render();break;
    case 'play-replay':if(timer){stopReplay();render();}else{if(cursor===null||cursor>=session.events.length-1)cursor=0;timer=setInterval(()=>{cursor++;if(cursor>=session.events.length-1){cursor=session.events.length-1;stopReplay();}render();},550);render();}break;
  }
});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='command-form'){const input=$('#command');if(input.value.trim())act(parseCommand(input.value));$('#command')?.focus();}else if(event.target.id==='note-form'){const val=$('#note').value;if(val.trim())act({type:'note',text:val});}else if(event.target.id==='accusation-form'){const f=new FormData(event.target);$('#modal').close();act({type:'accuse',suspect:f.get('suspect'),method:f.get('method'),motive:f.get('motive'),evidence:f.getAll('evidence')});}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='present-clue'){chosenClue=el.value;render();}else if(el.id==='character-select'){person=el.value;render();}else if(el.id==='actor-filter'){actorFilter=el.value;render();}else if(el.id==='type-filter'){typeFilter=el.value;render();}else if(el.id==='clock-filter'){includeClock=el.checked;render();}else if(el.id==='import-file'&&el.files[0]){const file=el.files[0];if(file.size>20_000_000){toast('Choose a save smaller than 20 MB.');return;}file.text().then(text=>{const imported=importSession(text);session=imported;healthCache=null;cursor=null;chat=null;stopReplay();persist();$('#modal').close();render();toast('Saved investigation restored, with its full history.');}).catch(err=>toast(`Could not import: ${err.message}`));el.value='';}});
document.addEventListener('input',event=>{if(event.target.id==='history-search'){query=event.target.value;$('#event-list').innerHTML=eventList();}else if(event.target.id==='history-cursor'){
  // Keep the range input itself mounted while dragging so pointer capture is preserved.
  stopReplay();cursor=Number(event.target.value);const w=selectedWorld(),e=session.events[selectedIndex()];
  if($('#event-detail'))$('#event-detail').innerHTML=eventDetail();
  $('#character-panel').innerHTML=characterPanel(w);
  $('.replay-state').innerHTML=`<span class="past-dot"></span><strong>Inspecting the past</strong><span>${timeLabel(e.minute)}</span>`;
  $('.replay-slider>span').textContent=`${selectedIndex()+1} / ${session.events.length} events`;
  $('.replay-bar>.soft-button').disabled=false;
  $('.play-replay').textContent='▶';$('.play-replay').setAttribute('aria-label','Play recorded history');
  $('.inspector-summary>div:nth-child(2)>strong').textContent=Object.values(w.npcs).reduce((n,a)=>n+a.beliefs.length,0);
  if($('#event-list'))$('#event-list').innerHTML=eventList();
  if($('.world-panel'))$('.world-panel').outerHTML=worldPanel(w);
}});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
render();if(saveError)toast('A previous save could not be loaded. The original remains until your next action; you are starting a fresh case.');
